//! Wolfram convention replay: SPL, angular frequency and signed wavenumbers.
//!
//! The fixture (`fixtures/wolfram-golden-v1.json`, generated by
//! `wolfram/conventions_golden.wls`) carries independent references with
//! explicit phasor signs, per audit-sonium-xem-20260921. Both harmonic
//! conventions are exercised so a sign drift between BEM and FEM adapters
//! fails here rather than in a coupled solve.

use num_complex::Complex64;
use serde::Deserialize;
use sonium_xem::{AcousticMedium, ConventionRegistry, HarmonicConvention, pressure_to_spl};

const FIXTURE: &str = include_str!("../fixtures/wolfram-golden-v1.json");

#[derive(Debug, Deserialize)]
struct SplCase {
    peak: String,
    spl_db: String,
}

#[derive(Debug, Deserialize)]
struct AngularCase {
    freq_hz: String,
    omega: String,
}

#[derive(Debug, Deserialize)]
struct WavenumberCase {
    freq_hz: String,
    c: String,
    k_minus: String,
    k_plus: String,
}

#[derive(Debug, Deserialize)]
struct Fixture {
    schema: String,
    spl: Vec<SplCase>,
    angular: Vec<AngularCase>,
    wavenumber: Vec<WavenumberCase>,
}

fn parse(value: &str) -> f64 {
    value.parse().expect("fixture value is a decimal")
}

fn parse_fixture() -> Fixture {
    let fixture: Fixture = serde_json::from_str(FIXTURE).expect("valid XEM convention fixture");
    assert_eq!(fixture.schema, "sonium-xem.wolfram-golden.v1");
    fixture
}

fn medium_with(
    freq_hz: f64,
    speed_of_sound: f64,
    convention: HarmonicConvention,
) -> AcousticMedium {
    AcousticMedium::try_new_with_conventions(
        sonium_xem::FrequencyHz::try_new(freq_hz).expect("valid frequency"),
        sonium_xem::SpeedOfSoundMPerS::try_new(speed_of_sound).expect("valid sound speed"),
        sonium_xem::DensityKgM3::try_new(1.21).expect("valid density"),
        ConventionRegistry {
            harmonic_time: convention,
            ..Default::default()
        },
    )
    .expect("valid medium")
}

#[test]
fn spl_matches_wolfram_reference() {
    let fixture = parse_fixture();
    assert_eq!(fixture.spl.len(), 3);
    for case in &fixture.spl {
        let peak = parse(&case.peak);
        let expected = parse(&case.spl_db);
        // Phase independence: the same peak magnitude at two phases.
        for phase in [0.0f64, 1.0] {
            let pressure = Complex64::new(peak * phase.cos(), peak * phase.sin());
            let actual = pressure_to_spl(pressure);
            assert!(
                (actual - expected).abs() <= 1e-9,
                "SPL({peak} @ {phase}): {actual} != wolfram {expected}"
            );
        }
    }
}

#[test]
fn angular_frequency_matches_wolfram() {
    let fixture = parse_fixture();
    for case in &fixture.angular {
        let medium = medium_with(parse(&case.freq_hz), 343.0, HarmonicConvention::ExpMinusIwt);
        let expected = parse(&case.omega);
        assert!(
            (medium.angular_frequency() - expected).abs() <= 1e-9,
            "omega({}) = {} != wolfram {expected}",
            case.freq_hz,
            medium.angular_frequency(),
        );
    }
}

#[test]
fn signed_wavenumbers_match_wolfram_both_conventions() {
    let fixture = parse_fixture();
    assert_eq!(fixture.wavenumber.len(), 3);
    for case in &fixture.wavenumber {
        let freq = parse(&case.freq_hz);
        let speed = parse(&case.c);
        let minus = medium_with(freq, speed, HarmonicConvention::ExpMinusIwt).wavenumber();
        let expected_minus = parse(&case.k_minus);
        assert!(
            (minus - expected_minus).abs() <= 1e-9 * expected_minus.abs().max(1.0),
            "k-({freq}): {minus} != wolfram {expected_minus}"
        );
        let plus = medium_with(freq, speed, HarmonicConvention::ExpPlusIwt).wavenumber();
        let expected_plus = parse(&case.k_plus);
        assert!(
            (plus - expected_plus).abs() <= 1e-9 * expected_plus.abs().max(1.0),
            "k+({freq}): {plus} != wolfram {expected_plus}"
        );
        // The two conventions must disagree in sign (outgoing factor flips).
        assert!(
            minus * plus < 0.0,
            "conventions must carry opposite spatial signs at {freq}"
        );
    }
}
